'use strict';
function openReportShare(kind){if(document.querySelector('.report-share-dialog'))return;const finance=kind==='finance';const dialog=document.createElement('dialog');dialog.className='report-share-dialog';dialog.setAttribute('aria-label',finance?'Chia sẻ báo cáo thu chi tuần':'Chia sẻ báo cáo tuần');dialog.innerHTML='<div class="modal-head"><span class="eyebrow">'+(finance?'BỨC TRANH THU CHI':'BỨC TRANH CÔNG VIỆC')+'</span><button type="button" class="icon-btn" id="close-report-share" aria-label="Đóng chia sẻ">×</button></div><h2>'+(finance?'Chia sẻ báo cáo thu chi tuần':'Chia sẻ báo cáo tuần')+'</h2><p class="help-copy">Link giữ nguyên báo cáo tại thời điểm tạo. Bạn có thể thu hồi trước khi hết hạn.'+(finance?' Báo cáo có số tiền chi, thu hồi và lãi/lỗ của từng dự án, nên hãy đặt mật khẩu và chỉ gửi cho người bạn tin tưởng.':'')+'</p><form id="report-share-form"><div class="fields-row"><label class="field">Quyền xem<select name="mode" id="report-share-mode"><option value="password">Có mật khẩu</option><option value="public" selected>Công khai qua link</option></select></label><label class="field">Thời hạn<select name="days">'+[1,3,5,7,10,15,30].map(d=>'<option value="'+d+'" '+(d===1?'selected':'')+'>'+d+' ngày</option>').join('')+'</select></label></div><label class="field" id="share-secret-field">Mật khẩu xem báo cáo<input name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" placeholder="Từ 8 ký tự" required></label><p class="share-access-help" id="share-access-help">Người xem cần link và mật khẩu bạn cung cấp.</p><button type="submit" class="btn primary" id="create-report-link">'+svgIcon('plus')+'Tạo link chia sẻ</button></form><p id="report-share-status" role="status"></p><section id="report-share-result" hidden><label class="field">Link vừa tạo<input id="created-report-url" readonly></label><div class="help-actions"><button type="button" class="btn" id="copy-report-url">'+svgIcon('attach')+'Sao chép link</button><a class="btn" id="open-created-report" target="_blank" rel="noopener noreferrer">Mở báo cáo ↗</a></div><small id="created-report-expiry"></small></section><section class="active-report-shares"><h3>Link đang hoạt động</h3><small>Xem bản báo cáo đã lưu, theo dõi thời hạn hoặc thu hồi link.</small><div id="report-shares-list" role="status">Đang tải…</div></section>';document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('#close-report-share').onclick=()=>dialog.close();dialog.showModal();const form=dialog.querySelector('form'),mode=form.elements.mode,password=form.elements.password,status=dialog.querySelector('#report-share-status');if(finance)mode.value='password';mode.onchange=()=>{const locked=mode.value==='password';dialog.querySelector('#share-secret-field').hidden=!locked;password.disabled=!locked;password.required=locked;if(!locked)password.value='';dialog.querySelector('#share-access-help').textContent=locked?'Người xem cần link và mật khẩu bạn cung cấp.':'Bất kỳ ai có link đều có thể xem, không cần đăng nhập.';};mode.onchange();async function load(){const node=dialog.querySelector('#report-shares-list');try{const result=await requestAPI('report-shares');if(!dialog.isConnected)return;node.innerHTML=result.shares.map(s=>'<article class="report-share-row"><div><strong>'+esc(s.title)+'</strong><small>'+(s.mode==='password'?'Có mật khẩu':'Công khai qua link')+' · Hết hạn '+new Date(s.expires).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+'</small></div><a class="btn" target="_blank" rel="noopener noreferrer" href="/report.html#owner='+esc(s.id)+'">Xem ↗</a><button type="button" class="btn danger" data-revoke-report="'+esc(s.id)+'">Thu hồi</button></article>').join('')||'<p class="empty">Chưa có link đang hoạt động.</p>';}catch(error){node.textContent=error.message;}}form.onsubmit=async e=>{e.preventDefault();const button=dialog.querySelector('#create-report-link');button.disabled=true;status.textContent='Đang tạo bản chia sẻ…';try{await flushCloud();if(dirty)throw Error('Cần đồng bộ dữ liệu trước khi tạo link báo cáo.');const result=await requestAPI('report-shares','POST',{mode:mode.value,days:Number(form.elements.days.value),...(finance?{kind:'finance'}:{}),...(mode.value==='password'?{password:password.value}:{})});password.value='';if(!dialog.isConnected)return;dialog.querySelector('#report-share-result').hidden=false;dialog.querySelector('#created-report-url').value=result.url;dialog.querySelector('#open-created-report').href=result.url;dialog.querySelector('#created-report-expiry').textContent=(result.mode==='password'?'Có mật khẩu':'Công khai qua link')+' · Hết hạn '+new Date(result.expires).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' (VN)';status.textContent='Đã tạo link. Sao chép để gửi cho người cần xem.';await load();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};dialog.querySelector('#copy-report-url').onclick=async()=>{const input=dialog.querySelector('#created-report-url');try{await navigator.clipboard.writeText(input.value);status.textContent='Đã sao chép link.';}catch{input.focus();input.select();status.textContent='Link đã được chọn. Nhấn Ctrl+C hoặc dùng Sao chép trên thiết bị.';}};dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-revoke-report]');if(!b)return;if(!b.dataset.confirmed){b.dataset.confirmed='yes';b.textContent='Xác nhận thu hồi';const cancel=document.createElement('button');cancel.type='button';cancel.className='btn';cancel.textContent='Hủy';cancel.onclick=()=>{delete b.dataset.confirmed;b.textContent='Thu hồi';cancel.remove();};b.after(cancel);return;}b.disabled=true;try{await requestAPI('report-shares','DELETE',{id:b.dataset.revokeReport});status.textContent='Đã thu hồi link.';await load();}catch(error){status.textContent=error.message;b.disabled=false;}});load();}
// Use the existing HSV wheel in the note editor; all values still save through name=color.
const noteFormBeforeWheel=noteForm;noteForm=function(n){noteFormBeforeWheel(n);const composer=$('.note-composer');if(!composer||contentReadOnly)return;const input=composer.querySelector('input[name=color]'),label=input?.closest('.note-color');if(!input||!label)return;const initial=input.value;input.type='hidden';const picker=document.createElement('details');picker.className='appearance-picker note-wheel-picker';picker.innerHTML='<summary><span>Màu thẻ</span><span class="appearance-value"><i id="project-color-swatch" style="background:'+initial+'"></i><b id="project-color-value">'+initial.toUpperCase()+'</b>⌄</span></summary><div class="color-picker-panel"><div class="color-wheel-wrap"><canvas id="project-color-wheel" width="220" height="220" tabindex="0" role="slider" aria-label="Bánh xe màu thẻ. Phím trái phải đổi sắc, lên xuống đổi độ bão hòa." aria-valuemin="0" aria-valuemax="360"></canvas><i id="color-wheel-marker"></i></div><label>Độ sáng<input id="color-brightness" type="range" min="0" max="100" step="1"></label><label>HEX<input id="project-hex" maxlength="7" pattern="#[a-fA-F0-9]{6}" value="'+initial+'" spellcheck="false"></label><div class="rgb-inputs">'+['R','G','B'].map((name,i)=>'<label>'+name+'<input type="number" id="project-rgb-'+i+'" min="0" max="255" step="1" aria-label="'+name+'"></label>').join('')+'</div><small id="project-rgb-code"></small></div>';picker.append(input);label.remove();composer.querySelector('.note-toolbar').before(picker);setupColorWheel(initial);};


/* v1.9.5 · Group the three note preferences into one desktop row.
   Reparent existing controls only; preserve all inputs, handlers and saved values. */
const noteFormBeforeQuickOptions=noteForm;
noteForm=function(n){
  noteFormBeforeQuickOptions(n);
  const composer=document.querySelector('#editor.keep-editor .note-composer');
  if(!composer)return;
  const reminder=composer.querySelector('.note-reminder-options');
  const kind=composer.querySelector('.note-type-field');
  const color=composer.querySelector('.note-wheel-picker');
  if(!reminder||!kind||!color)return;
  const group=document.createElement('div');
  group.className='note-quick-options';
  group.setAttribute('aria-label','Tùy chọn ghi chú');
  reminder.before(group);
  group.append(reminder,kind,color);
};
